//
// Premium 3-step doctor registration page.
// Preserves all existing backend API contracts:
//   Step 1: auth/register (displayName, email, password, userType=Doctor)
//   Step 2: doctors/register (registrationNumber, specialty, hospitalClinic, phoneNumber)
//   Step 3: Review before submit

import { useState, useId } from 'react'
import { Navigate, useNavigate, Link } from 'react-router-dom'
import { z } from 'zod'

import { apiClient } from '../../services/apiClient'
import { useAppDispatch, useAppSelector } from '../../store/hooks'
import { registerDoctorUser } from '../../store/slices/authSlice'
import { AuthHero } from '../../components/auth/AuthHero'
import { AuthStepper } from '../../components/auth/AuthStepper'
import { PasswordField } from '../../components/auth/PasswordField'
import logoUrl from '../../assets/logo.png'
import registerBg from '../../assets/Register.webp'

import '../../styles/auth-shell.css'

// ── Validation schemas ────────────────────────────────────────────────────────

const accountSchema = z.object({
  displayName: z.string().trim().min(1, 'Enter your full name.').max(120, 'Name is too long.'),
  email:       z.string().email('Enter a valid email address.'),
  password:    z.string().min(12, 'Password must be at least 12 characters.').max(128),
  confirm:     z.string().min(1, 'Confirm your password.'),
}).refine((d) => d.password === d.confirm, {
  message: 'Passwords do not match.',
  path: ['confirm'],
})

const professionalSchema = z.object({
  registrationNumber: z.string().trim().min(4, 'Enter your registration number (min 4 characters).').max(30),
  specialty:          z.string().trim().max(120).optional(),
  hospitalClinic:     z.string().trim().max(200).optional(),
  phoneNumber:        z.string().trim().max(20).optional(),
})

// ── Step definitions ──────────────────────────────────────────────────────────

const STEPS = [
  { label: 'Account'     },
  { label: 'Professional'},
  { label: 'Review'      },
]

// ── Component ─────────────────────────────────────────────────────────────────

export function DoctorRegisterPage() {
  const dispatch   = useAppDispatch()
  const navigate   = useNavigate()
  const uid        = useId()

  const { isAuthenticated, user, status: authStatus, error: authError } = useAppSelector((s) => s.auth)

  // ── All hooks must be called unconditionally (rules-of-hooks) ─────────────

  const [step, setStep] = useState(0)

  // Step 1 — Account
  const [displayName, setDisplayName] = useState('')
  const [email,       setEmail]       = useState('')
  const [password,    setPassword]    = useState('')
  const [confirm,     setConfirm]     = useState('')

  // Step 2 — Professional
  const [registrationNumber, setRegistrationNumber] = useState('')
  const [specialty,          setSpecialty]          = useState('')
  const [hospitalClinic,     setHospitalClinic]     = useState('')
  const [phoneNumber,        setPhoneNumber]        = useState('')

  // Error + loading
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({})
  const [apiError,    setApiError]    = useState('')
  const [submitting,  setSubmitting]  = useState(false)

  // Redirect if already authenticated — after all hooks
  if (isAuthenticated) {
    return <Navigate to={user?.role === 'DOCTOR' ? '/doctor-status' : '/dashboard'} replace />
  }


  // ── Helpers ───────────────────────────────────────────────────────────────

  function clearErrors() {
    setFieldErrors({})
    setApiError('')
  }

  // ── Step navigation ───────────────────────────────────────────────────────

  function handleNext() {
    clearErrors()

    if (step === 0) {
      const result = accountSchema.safeParse({ displayName, email, password, confirm })
      if (!result.success) {
        const errs: Record<string, string> = {}
        for (const issue of result.error.issues) {
          const key = String(issue.path[0] ?? 'form')
          if (!errs[key]) errs[key] = issue.message
        }
        setFieldErrors(errs)
        return
      }
    }

    if (step === 1) {
      const result = professionalSchema.safeParse({ registrationNumber, specialty, hospitalClinic, phoneNumber })
      if (!result.success) {
        const errs: Record<string, string> = {}
        for (const issue of result.error.issues) {
          const key = String(issue.path[0] ?? 'form')
          if (!errs[key]) errs[key] = issue.message
        }
        setFieldErrors(errs)
        return
      }
    }

    setStep((s) => s + 1)
  }

  function handleBack() {
    clearErrors()
    setStep((s) => s - 1)
  }

  // ── Final submission ──────────────────────────────────────────────────────
  // Two-phase: (1) create auth account, (2) POST doctor profile
  // Preserves existing API contract exactly.

  async function handleSubmit() {
    clearErrors()
    setSubmitting(true)

    try {
      // Phase 1: create the user account
      const authResult = await dispatch(
        registerDoctorUser({ displayName, email, password })
      )

      if (!registerDoctorUser.fulfilled.match(authResult)) {
        setApiError(authResult.payload ?? 'Account creation failed. Check your details and try again.')
        setStep(0)
        setSubmitting(false)
        return
      }

      // Phase 2: POST doctor professional profile
      try {
        await apiClient.post('/doctors/register', {
          registrationNumber: registrationNumber.trim(),
          specialty:     specialty.trim()     || null,
          hospitalClinic: hospitalClinic.trim() || null,
          phoneNumber:   phoneNumber.trim()   || null,
        })
      } catch {
        // Account created but profile incomplete — surface non-fatal error
        setApiError(
          'Your account was created, but the professional profile could not be saved. ' +
          'You can complete it after verification.'
        )
        navigate('/doctor-status', { replace: true })
        return
      }

      navigate('/doctor-status', { replace: true })
    } finally {
      setSubmitting(false)
    }
  }

  const isLoading = authStatus === 'loading' || submitting

  // ── Render ─────────────────────────────────────────────────────────────────

  return (
    <main className="auth-shell-page" aria-label="Doctor registration">
      <div className="auth-container" data-mode="register">

        {/* ── Hero panel (right on desktop for register mode) ── */}
        <AuthHero
          imageSrc={registerBg}
          logoSrc={logoUrl}
          headline="Join FamilyVeda as a Clinician"
          subline="Your profile will be reviewed before clinical access is enabled."
        />

        {/* ── Form panel ── */}
        <div className="auth-form-panel">
          {/* Form-panel logo mark */}
          <div className="auth-form-logo-mark">
            <img src={logoUrl} alt="" aria-hidden="true" width={32} height={32} />
            <span className="auth-form-logo-mark-name">FamilyVeda</span>
          </div>

          {/* Title */}
          <h1 className="auth-form-title">
            {step === 0 && 'Create your account'}
            {step === 1 && 'Professional details'}
            {step === 2 && 'Review & submit'}
          </h1>
          <p className="auth-form-subtitle">
            {step === 0 && 'Enter your account credentials.'}
            {step === 1 && 'Enter your clinical registration information.'}
            {step === 2 && 'Review your details before submitting for verification.'}
          </p>

          {/* Stepper */}
          <AuthStepper steps={STEPS} currentStep={step} />

          {/* API / auth error */}
          {(apiError || authError) && (
            <div className="auth-alert-error" role="alert">
              <span>⚠</span>
              <span>{apiError || authError}</span>
            </div>
          )}

          {/* ── Step 1: Account ── */}
          {step === 0 && (
            <section aria-labelledby={`${uid}-step1-heading`}>
              <h2 id={`${uid}-step1-heading`} className="sr-only">Step 1: Account credentials</h2>

              <div className="auth-field-grid">
                {/* Full Name */}
                <div className="auth-field auth-field-full">
                  <label htmlFor={`${uid}-name`}>
                    Full name <span aria-hidden="true">*</span>
                  </label>
                  <input
                    id={`${uid}-name`}
                    type="text"
                    value={displayName}
                    autoComplete="name"
                    placeholder="Dr. Jane Smith"
                    required
                    maxLength={120}
                    aria-invalid={fieldErrors.displayName ? 'true' : undefined}
                    aria-describedby={fieldErrors.displayName ? `${uid}-name-error` : undefined}
                    onChange={(e) => setDisplayName(e.target.value)}
                  />
                  {fieldErrors.displayName && (
                    <span id={`${uid}-name-error`} className="auth-field-error" role="alert">
                      {fieldErrors.displayName}
                    </span>
                  )}
                </div>

                {/* Email */}
                <div className="auth-field auth-field-full">
                  <label htmlFor={`${uid}-email`}>
                    Email address <span aria-hidden="true">*</span>
                  </label>
                  <input
                    id={`${uid}-email`}
                    type="email"
                    value={email}
                    autoComplete="email"
                    placeholder="doctor@hospital.lk"
                    required
                    aria-invalid={fieldErrors.email ? 'true' : undefined}
                    aria-describedby={fieldErrors.email ? `${uid}-email-error` : undefined}
                    onChange={(e) => setEmail(e.target.value)}
                  />
                  {fieldErrors.email && (
                    <span id={`${uid}-email-error`} className="auth-field-error" role="alert">
                      {fieldErrors.email}
                    </span>
                  )}
                </div>

                {/* Password */}
                <div className="auth-field">
                  <PasswordField
                    id={`${uid}-pw`}
                    label="Password"
                    value={password}
                    autoComplete="new-password"
                    placeholder="Min 12 characters"
                    required
                    showStrength
                    error={fieldErrors.password}
                    onChange={setPassword}
                  />
                </div>

                {/* Confirm Password */}
                <div className="auth-field">
                  <PasswordField
                    id={`${uid}-pw2`}
                    label="Confirm password"
                    value={confirm}
                    autoComplete="new-password"
                    placeholder="Repeat password"
                    required
                    error={fieldErrors.confirm}
                    onChange={setConfirm}
                  />
                </div>
              </div>

              <div className="auth-nav-row">
                <button
                  type="button"
                  className="auth-btn-primary"
                  onClick={handleNext}
                  disabled={isLoading}
                >
                  Continue
                </button>
              </div>

              <div className="auth-switch-row">
                Already have an account?{' '}
                <Link to="/login">Sign in</Link>
              </div>
            </section>
          )}

          {/* ── Step 2: Professional ── */}
          {step === 1 && (
            <section aria-labelledby={`${uid}-step2-heading`}>
              <h2 id={`${uid}-step2-heading`} className="sr-only">Step 2: Professional details</h2>

              <div className="auth-field-grid">
                {/* Registration Number */}
                <div className="auth-field">
                  <label htmlFor={`${uid}-regno`}>
                    SLMC registration number <span aria-hidden="true">*</span>
                  </label>
                  <input
                    id={`${uid}-regno`}
                    type="text"
                    value={registrationNumber}
                    placeholder="e.g. SLMC-9999"
                    required
                    minLength={4}
                    maxLength={30}
                    aria-invalid={fieldErrors.registrationNumber ? 'true' : undefined}
                    aria-describedby={fieldErrors.registrationNumber ? `${uid}-regno-error` : undefined}
                    onChange={(e) => setRegistrationNumber(e.target.value)}
                  />
                  {fieldErrors.registrationNumber && (
                    <span id={`${uid}-regno-error`} className="auth-field-error" role="alert">
                      {fieldErrors.registrationNumber}
                    </span>
                  )}
                </div>

                {/* Phone */}
                <div className="auth-field">
                  <label htmlFor={`${uid}-phone`}>Professional phone</label>
                  <input
                    id={`${uid}-phone`}
                    type="tel"
                    value={phoneNumber}
                    autoComplete="tel"
                    placeholder="+94 77 000 0000"
                    maxLength={20}
                    aria-invalid={fieldErrors.phoneNumber ? 'true' : undefined}
                    aria-describedby={fieldErrors.phoneNumber ? `${uid}-phone-error` : undefined}
                    onChange={(e) => setPhoneNumber(e.target.value)}
                  />
                  {fieldErrors.phoneNumber && (
                    <span id={`${uid}-phone-error`} className="auth-field-error" role="alert">
                      {fieldErrors.phoneNumber}
                    </span>
                  )}
                </div>

                {/* Specialty */}
                <div className="auth-field auth-field-full">
                  <label htmlFor={`${uid}-specialty`}>Specialization</label>
                  <input
                    id={`${uid}-specialty`}
                    type="text"
                    value={specialty}
                    placeholder="e.g. General Practice, Cardiology"
                    maxLength={120}
                    onChange={(e) => setSpecialty(e.target.value)}
                  />
                </div>

                {/* Hospital / Clinic */}
                <div className="auth-field auth-field-full">
                  <label htmlFor={`${uid}-hospital`}>Hospital / Clinic</label>
                  <input
                    id={`${uid}-hospital`}
                    type="text"
                    value={hospitalClinic}
                    placeholder="e.g. National Hospital, Colombo"
                    maxLength={200}
                    onChange={(e) => setHospitalClinic(e.target.value)}
                  />
                </div>
              </div>

              <div className="auth-nav-row">
                <button
                  type="button"
                  className="auth-btn-secondary"
                  onClick={handleBack}
                  disabled={isLoading}
                >
                  Back
                </button>
                <button
                  type="button"
                  className="auth-btn-primary"
                  onClick={handleNext}
                  disabled={isLoading}
                >
                  Review details
                </button>
              </div>
            </section>
          )}

          {/* ── Step 3: Review ── */}
          {step === 2 && (
            <section aria-labelledby={`${uid}-step3-heading`}>
              <h2 id={`${uid}-step3-heading`} className="sr-only">Step 3: Review and submit</h2>

              <ul className="auth-review-list" aria-label="Registration summary">
                <li className="auth-review-item">
                  <span className="auth-review-icon" aria-hidden="true">✓</span>
                  <div>
                    <p className="auth-review-label">Account</p>
                    <p className="auth-review-value">{displayName}</p>
                    <p className="auth-review-value">{email}</p>
                  </div>
                </li>
                <li className="auth-review-item">
                  <span className="auth-review-icon" aria-hidden="true">✓</span>
                  <div>
                    <p className="auth-review-label">Professional</p>
                    <p className="auth-review-value">Reg: {registrationNumber}</p>
                    {specialty     && <p className="auth-review-value">{specialty}</p>}
                    {hospitalClinic && <p className="auth-review-value">{hospitalClinic}</p>}
                    {phoneNumber   && <p className="auth-review-value">{phoneNumber}</p>}
                  </div>
                </li>
              </ul>

              {/* Verification notice — preserves doctor verification gating */}
              <div className="auth-pending-notice" role="note">
                <strong>Verification required</strong>
                Your profile will be reviewed by an administrator before clinical access is enabled.
                You will not have unrestricted clinical access until verification is complete.
              </div>

              <div className="auth-nav-row">
                <button
                  type="button"
                  className="auth-btn-secondary"
                  onClick={handleBack}
                  disabled={isLoading}
                >
                  Back
                </button>
                <button
                  type="button"
                  className="auth-btn-primary"
                  onClick={handleSubmit}
                  disabled={isLoading}
                  aria-busy={isLoading}
                >
                  {isLoading
                    ? <><span className="auth-spinner" aria-hidden="true" /> Creating account…</>
                    : 'Create doctor account'
                  }
                </button>
              </div>

              <div className="auth-switch-row">
                Already have an account?{' '}
                <Link to="/login">Sign in</Link>
              </div>
            </section>
          )}
        </div>
      </div>
    </main>
  )
}
